/* ─── APP ─────────────────────────────────────────────────────────────────── */
export default function App(){
  const [page,setPage]=useState("home");
  const [email,setEmail]=useState(null);
  const [otpCode,setOtpCode]=useState(null);
  const [votedFor,setVotedFor]=useState(null);
  const [votes,setVotes]=useState(INIT_VOTES);
  const [unlocked,setUnlocked]=useState(false);
  const [toast,setToast]=useState(null);
  const showToast=useCallback((msg,type="success")=>setToast({msg,type}),[]);

  const refreshVotes = useCallback(async ()=>{
    try{
      const res = await fetch(`${API_BASE}/results`);
      if(!res.ok) throw new Error('Failed to load results');
      const data = await res.json();
      const byId = data.reduce((acc,row)=>({ ...acc, [row.id]: row.vote_count }), {});
      setVotes(v=>({ ...INIT_VOTES, ...byId }));
    }catch(e){
      console.error('Results fetch failed', e);
    }
  },[]);

  useEffect(()=>{refreshVotes()},[refreshVotes]);

  const handleVerified=(e,otp)=>{setEmail(e);setOtpCode(otp);setPage("vote");showToast("✓ Verified! Cast your vote now.")};
  const handleVote=(pid)=>{
    setVotedFor(pid);
    refreshVotes();
    showToast("🎉 Vote recorded & encrypted!");
  };
  const handleSim=(pid,n)=>{setVotes(v=>({...v,[pid]:v[pid]+n}));showToast(`+${n} votes → ${PARTIES.find(p=>p.id===pid)?.abbr}`)};

  const nav=[{id:"home",l:"🏠 Home"},{id:"vote",l:"🗳️ Vote"},{id:"results",l:"📊 Results"},{id:"admin",l:"⚙️ Admin"}];

  return(
    <>
      <style>{STYLES}</style>
      <div className="bg">
        <div className="flagbar"/>
        <header className="hdr">
          <div className="hdr-logo">IN</div>
          <div><div className="hdr-name">Bharat<span>Vote</span></div><div className="hdr-sub">National Election Platform</div></div>
          <nav className="hdr-nav">
            {nav.map(n=><button key={n.id} className={`hn ${page===n.id?"active":""}`} onClick={()=>setPage(n.id)}>{n.l}</button>)}
          </nav>
          <div className="hdr-right">
            <div className="live-badge"><div className="live-dot"/>LIVE</div>
            {email&&<button className="btn btn-ghost" style={{fontSize:12,padding:"5px 13px"}} onClick={()=>{setEmail(null);setVotedFor(null);setPage("home")}}>📧 {email} · Logout</button>}
          </div>
        </header>
        <main className="main">
          {page==="home"&&<HomePage onVote={()=>setPage(email?"vote":"otp")}/>}
          {page==="otp"&&<OtpFlow onVerified={handleVerified}/>}
          {page==="vote"&&(email?<VotePage email={email} otp={otpCode} votes={votes} onVote={handleVote} votedFor={votedFor}/>:<OtpFlow onVerified={handleVerified}/>)}
          {page==="results"&&<ResultsPage votes={votes} unlocked={unlocked}/>}
          {page==="admin"&&<AdminPage votes={votes} unlocked={unlocked} setUnlocked={setUnlocked} onSim={handleSim}/>}
        </main>
        {toast&&<Toast msg={toast.msg} type={toast.type} onClose={()=>setToast(null)}/>}
      </div>
    </>
  );
}